// src/components/Projects.js
import React from 'react';

function Projects() {
  return (
    <section id="projects">
      <h2>Projects</h2>
      <p>
        Project One<br />
        A web application for managing tasks. Built with React and Node.js.<br />
        <a href="https://github.com/yourusername/project-one" target="_blank" rel="noopener noreferrer">View on GitHub</a>
      </p>
      <p>
        Project Two<br />
        A data visualization dashboard using D3.js.<br />
        <a href="https://github.com/yourusername/project-two" target="_blank" rel="noopener noreferrer">View on GitHub</a>
      </p>
    </section>
  );
}

export default Projects;
